using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search capability to the agent via the Brave Search API.
/// Falls back to a simulated search if BRAVE_API_KEY is not configured.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly string? _apiKey;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _apiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
    }

    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, URLs, and descriptions.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (string.IsNullOrWhiteSpace(_apiKey))
        {
            return GetSimulatedResults(query, maxResults);
        }

        try
        {
            var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");
            request.Headers.Add("Accept", "application/json");
            request.Headers.Add("X-Subscription-Token", _apiKey);

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>();
            var results = new List<string>();

            if (json.TryGetProperty("web", out var web) &&
                web.TryGetProperty("results", out var webResults))
            {
                foreach (var result in webResults.EnumerateArray().Take(maxResults))
                {
                    var title = result.GetProperty("title").GetString();
                    var url = result.GetProperty("url").GetString();
                    var description = result.TryGetProperty("description", out var desc)
                        ? desc.GetString() : "No description available";

                    results.Add($"Title: {title}\nURL: {url}\nDescription: {description}");
                }
            }

            return results.Count > 0
                ? string.Join("\n---\n", results)
                : "No results found for the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Falling back to simulated results.\n\n"
                + GetSimulatedResults(query, maxResults);
        }
    }

    private static string GetSimulatedResults(string query, int maxResults)
    {
        var results = new List<string>
        {
            $"Title: Overview of {query} - Wikipedia\nURL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}\nDescription: A comprehensive encyclopedic overview covering the history, key concepts, and current state of {query}.",
            $"Title: Latest Research on {query}\nURL: https://scholar.example.com/{Uri.EscapeDataString(query)}\nDescription: Recent academic papers and research findings related to {query}, including peer-reviewed studies and meta-analyses.",
            $"Title: {query}: A Practical Guide\nURL: https://guide.example.com/{Uri.EscapeDataString(query)}\nDescription: An in-depth practical guide explaining {query} with real-world examples, best practices, and common pitfalls.",
            $"Title: The Future of {query}\nURL: https://tech.example.com/future-{Uri.EscapeDataString(query)}\nDescription: Expert predictions and trend analysis on how {query} is expected to evolve in the coming years.",
            $"Title: {query} FAQ and Common Questions\nURL: https://faq.example.com/{Uri.EscapeDataString(query)}\nDescription: Frequently asked questions about {query} with detailed answers from domain experts.",
        };

        var selected = results.Take(maxResults);
        return "[Simulated results — set BRAVE_API_KEY for live web search]\n\n"
            + string.Join("\n---\n", selected);
    }
}

