using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build host with DI ---
var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient();

builder.Services.AddSingleton<NoteTool>();
builder.Services.AddSingleton<WebSearchTool>();

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, apiKey));

using var host = builder.Build();

// --- Resolve services ---
var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteTool = host.Services.GetRequiredService<NoteTool>();
var searchTool = host.Services.GetRequiredService<WebSearchTool>();

// --- Set up the agent with tools ---
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the SearchWebAsync tool.
        2. Saving important findings as notes using the SaveNote tool.
        3. After gathering enough information (at least 3-5 searches and notes),
           retrieve all notes with GetAllNotes and produce a comprehensive summary.

        Research strategy:
        - Start with a broad search, then drill into specific subtopics.
        - Save a note for each significant finding — include the source URL.
        - Cover different angles: definitions, history, current state, future outlook.
        - End with a well-structured summary that synthesizes all your notes.
        """,
};

var agentOptions = new AgentInvokeOptions
{
    MaximumIterations = 15,
    Tools = [
        AIFunctionFactory.Create(searchTool.SearchWebAsync),
        AIFunctionFactory.Create(noteTool.SaveNote),
        AIFunctionFactory.Create(noteTool.GetAllNotes),
        AIFunctionFactory.Create(noteTool.GetNotesByTopic),
    ],
    ModelOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

// --- Get the research topic ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a topic to research: ");
    topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
}

Console.WriteLine($"\nResearching: {topic}");
Console.WriteLine("This may take a moment...\n");

// --- Run the agent ---
var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

await foreach (var message in agent.InvokeStreamingAsync(history, agentOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine($"\n--- Research complete. {noteTool.Notes.Count} notes collected. ---");

